// Reproducible trusted firmware source, never character JSON or account data.
import {build} from 'esbuild';
import {deflateSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {readFile,writeFile} from 'node:fs/promises';
const root=new URL('../',import.meta.url);
const result=await build({entryPoints:[new URL('./beyond-device-entry.js',import.meta.url).pathname],bundle:true,format:'iife',target:'es2022',minify:true,write:false,legalComments:'none',metafile:true});
const source=result.outputFiles[0].contents,packed=deflateSync(source,{level:9}),digest=createHash('sha256').update(source).digest('hex');
const header=`/* Generated by scripts/build-beyond-bundle.js. Pocket rules only; no PG data. */\n#pragma once\n#define PD_BEYOND_BUNDLE_SIZE ${source.length}u\n#define PD_BEYOND_BUNDLE_SHA "${digest}"\nstatic const unsigned char pd_beyond_bundle[]={\n${Array.from({length:Math.ceil(packed.length/20)},(_,i)=>' '+[...packed.subarray(i*20,i*20+20)].map(n=>'0x'+n.toString(16).padStart(2,'0')).join(',')+',').join('\n')}\n};\n`;
const target=new URL('firmware/core/beyond_bundle.h',root);
if(process.argv.includes('--check')){
  if(await readFile(target,'utf8')!==header)throw Error('Beyond firmware bundle is stale: run node scripts/build-beyond-bundle.js');
}else await writeFile(target,header);
console.log(`Beyond rules: ${Object.keys(result.metafile.inputs).length} modules, ${source.length} source bytes, ${packed.length} packed bytes, SHA256 ${digest}`);
